-- Ejecutar una sola vez sobre el piloto existente. No reinstalar 001 ni 002.
begin;
create table public.project_roles(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.content(id),name text not null check(length(name) between 2 and 80),slots integer not null check(slots between 1 and 20));
create table public.project_members(project_id uuid references public.content(id),user_id uuid references public.profiles(id),role_id uuid references public.project_roles(id),status text not null check(status in ('pending','active','declined','left')),motivation text not null check(length(motivation) between 10 and 2000),reason text not null default '',created_at timestamptz default now(),primary key(project_id,user_id));
create table public.project_tasks(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.content(id),title text not null check(length(title) between 3 and 200),assignee_id uuid references public.profiles(id),status text not null default 'todo' check(status in ('todo','doing','done')),due_date date,created_at timestamptz default now());
create index project_members_user on public.project_members(user_id);
create index project_tasks_project on public.project_tasks(project_id);
create function public.leads_project(p_project uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.active_member() and exists(select 1 from public.content where id=p_project and kind='project' and(owner_id=auth.uid() or public.is_admin())) $$;
create function public.in_project(p_project uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.leads_project(p_project) or(public.active_member() and exists(select 1 from public.project_members where project_id=p_project and user_id=auth.uid() and status='active')) $$;
alter table public.project_roles enable row level security;
alter table public.project_members enable row level security;
alter table public.project_tasks enable row level security;
create policy roles_read on public.project_roles for select to authenticated using(public.can_read_content(project_id));
create policy members_read on public.project_members for select to authenticated using(public.active_member() and(user_id=auth.uid() or public.in_project(project_id)));
create policy tasks_read on public.project_tasks for select to authenticated using(public.in_project(project_id));
create function public.add_project_role(p_project uuid,p_name text,p_slots integer) returns void language plpgsql security definer set search_path='' as $$ begin if not public.leads_project(p_project) then raise exception 'Solo el líder puede definir roles';end if;if(select count(*) from public.project_roles where project_id=p_project)>=10 then raise exception 'Máximo 10 roles';end if;insert into public.project_roles(project_id,name,slots) values(p_project,trim(p_name),p_slots);end $$;
create function public.apply_project(p_project uuid,p_role uuid,p_motivation text) returns void language plpgsql security definer set search_path='' as $$ begin perform public.require_active();perform 1 from public.content where id=p_project and kind='project' and public.can_read_content(id) for update;if not found then raise exception 'Proyecto no disponible';end if;if public.leads_project(p_project) then raise exception 'Ya lideras el proyecto';end if;if not exists(select 1 from public.project_roles where id=p_role and project_id=p_project) then raise exception 'Rol no disponible';end if;if exists(select 1 from public.project_members where project_id=p_project and user_id=auth.uid() and status in('pending','active')) then raise exception 'Ya tienes una solicitud o participación';end if;insert into public.project_members(project_id,user_id,role_id,status,motivation) values(p_project,auth.uid(),p_role,'pending',trim(p_motivation)) on conflict(project_id,user_id) do update set role_id=excluded.role_id,status='pending',motivation=excluded.motivation,reason='';end $$;
create function public.review_project_member(p_project uuid,p_user uuid,p_approve boolean,p_reason text) returns void language plpgsql security definer set search_path='' as $$ declare candidate public.project_members;limit_slots integer;begin if not public.leads_project(p_project) then raise exception 'Solo el líder puede revisar solicitudes';end if;perform 1 from public.content where id=p_project for update;select * into candidate from public.project_members where project_id=p_project and user_id=p_user for update;if candidate.status is distinct from 'pending' then raise exception 'Solicitud no disponible';end if;if length(trim(p_reason))<5 then raise exception 'Explica la decisión';end if;if p_approve then if not exists(select 1 from public.profiles where id=p_user and status='active') then raise exception 'El usuario no tiene acceso activo';end if;select slots into limit_slots from public.project_roles where id=candidate.role_id;if(select count(*) from public.project_members where project_id=p_project and role_id=candidate.role_id and status='active')>=limit_slots then raise exception 'No quedan cupos en el rol';end if;end if;update public.project_members set status=case when p_approve then 'active' else 'declined' end,reason=p_reason where project_id=p_project and user_id=p_user;insert into public.audit_log(actor_id,action,target_id,details) values(auth.uid(),'project_review',p_project,p_user::text||': '||p_reason);end $$;
create function public.leave_project(p_project uuid,p_user uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$ begin perform public.require_active();if auth.uid()<>p_user and not public.leads_project(p_project) then raise exception 'Sin permiso';end if;if length(trim(p_reason))<10 then raise exception 'Explica el motivo (mínimo 10 caracteres)';end if;update public.project_members set status='left',reason=p_reason where project_id=p_project and user_id=p_user and status in('active','pending');update public.project_tasks set assignee_id=null where project_id=p_project and assignee_id=p_user and status<>'done';insert into public.audit_log(actor_id,action,target_id,details) values(auth.uid(),'project_leave',p_project,p_user::text||': '||p_reason);end $$;
create function public.save_project_task(p_id uuid,p_project uuid,p_title text,p_assignee uuid,p_due date) returns void language plpgsql security definer set search_path='' as $$ begin if not public.leads_project(p_project) then raise exception 'Solo el líder puede gestionar tareas';end if;if p_assignee is not null and not exists(select 1 from public.profiles where id=p_assignee and status='active') then raise exception 'El responsable no tiene acceso activo';end if;if p_assignee is not null and not exists(select 1 from public.content where id=p_project and owner_id=p_assignee) and not exists(select 1 from public.project_members where project_id=p_project and user_id=p_assignee and status='active') then raise exception 'El responsable no pertenece al equipo';end if;if p_id is null then insert into public.project_tasks(project_id,title,assignee_id,due_date) values(p_project,p_title,p_assignee,p_due);else update public.project_tasks set title=p_title,assignee_id=p_assignee,due_date=p_due where id=p_id and project_id=p_project;end if;end $$;
create function public.set_project_task_status(p_task uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$ declare task public.project_tasks;begin perform public.require_active();select * into task from public.project_tasks where id=p_task for update;if task.id is null or not public.in_project(task.project_id) or not(public.leads_project(task.project_id) or task.assignee_id=auth.uid()) then raise exception 'Solo líder o responsable puede cambiar el estado';end if;update public.project_tasks set status=p_status where id=p_task;insert into public.audit_log(actor_id,action,target_id,details) values(auth.uid(),'project_task_status',task.project_id,p_task::text||': '||p_status);end $$;
-- A collaborator can publish an advance, but cannot edit someone else's content.
create or replace function public.validate_content_parent() returns trigger language plpgsql security definer set search_path='' as $$ declare parent_kind text;begin if new.parent_id is not null then select kind into parent_kind from public.content where id=new.parent_id;if new.kind='solution' and parent_kind<>'case' then raise exception 'La solución pertenece a un builder case';end if;if new.kind='update' and parent_kind<>'project' then raise exception 'El avance pertenece a un proyecto';end if;if exists(with recursive ancestors as(select c.id,c.parent_id from public.content c where c.id=new.parent_id union select c.id,c.parent_id from public.content c join ancestors a on c.id=a.parent_id) select 1 from ancestors where id=new.id) then raise exception 'La vinculación crea un ciclo';end if;end if;return new;end $$;
revoke all on public.project_roles,public.project_members,public.project_tasks from anon,authenticated;
grant select on public.project_roles,public.project_members,public.project_tasks to authenticated;
do $$ declare f record;begin for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('leads_project','in_project','add_project_role','apply_project','review_project_member','leave_project','save_project_task','set_project_task_status') loop execute format('revoke all on function %s from public,anon',f.signature);execute format('grant execute on function %s to authenticated',f.signature);end loop;end $$;
create or replace function public.save_content(p_id uuid,p_kind text,p_title text,p_body text,p_url text default null,p_parent uuid default null,p_start timestamptz default null,p_end timestamptz default null,p_capacity integer default null,p_published boolean default true,p_join_url text default null) returns uuid language plpgsql security definer set search_path='' as $$
declare target uuid; existing public.content; allowed boolean;
begin perform public.require_active();
if p_kind='solution' then raise exception 'Entrega soluciones mediante el builder case';end if;
allowed:=public.is_editor() or p_kind in ('post','project','update');
if not allowed then raise exception 'Solo organizadores o mentores pueden publicar este contenido';end if;
if p_parent is not null and not public.can_read_content(p_parent) then raise exception 'Contenido padre no disponible';end if;
if p_kind='update' and not exists(select 1 from public.content where id=p_parent and kind='project' and (owner_id=auth.uid() or public.is_editor() or public.in_project(p_parent))) then raise exception 'Solo responsable o mentor puede publicar avances';end if;
if p_kind in ('event','webinar') and (p_start is null or p_end is null or p_end<=p_start) then raise exception 'Define inicio y fin válidos';end if;
if p_kind='case' and (p_end is null) then raise exception 'Define el cierre del builder case';end if;
if p_id is null then
 if (select count(*) from public.content where owner_id=auth.uid() and created_at>now()-interval '1 minute')>=10 then raise exception 'Espera antes de crear más contenido';end if;
 insert into public.content(kind,title,body,url,owner_id,parent_id,starts_at,ends_at,capacity,published) values(p_kind,p_title,p_body,nullif(p_url,''),auth.uid(),p_parent,p_start,p_end,p_capacity,p_published) returning id into target;
else
 select * into existing from public.content where id=p_id for update;
 if existing.id is null or not(public.is_admin() or existing.owner_id=auth.uid()) or existing.kind<>p_kind then raise exception 'No puedes editar este contenido';end if;
 update public.content set title=p_title,body=p_body,url=nullif(p_url,''),parent_id=p_parent,starts_at=p_start,ends_at=p_end,capacity=p_capacity,published=p_published where id=p_id;target:=p_id;
end if;
if p_join_url is not null and p_join_url<>'' then
 if p_kind not in ('event','webinar') then raise exception 'El enlace de acceso solo aplica a eventos';end if;
 insert into public.event_access(content_id,join_url) values(target,p_join_url) on conflict(content_id) do update set join_url=excluded.join_url;
end if;
insert into public.audit_log(actor_id,action,target_id) values(auth.uid(),'save_content',target);return target;end $$;



create table public.project_messages(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.content(id),author_id uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 2000),created_at timestamptz not null default now());
create index project_messages_project on public.project_messages(project_id,created_at);
alter table public.project_messages enable row level security;
create policy messages_read on public.project_messages for select to authenticated using(public.in_project(project_id));
revoke all on public.project_messages from anon,authenticated;
grant select on public.project_messages to authenticated;
create function public.add_project_message(p_project uuid,p_body text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.in_project(p_project) then raise exception 'Solo el equipo puede participar';end if;if(select count(*) from public.project_messages where author_id=auth.uid() and created_at>now()-interval '1 minute')>=10 then raise exception 'Espera antes de enviar más mensajes';end if;insert into public.project_messages(project_id,author_id,body) values(p_project,auth.uid(),trim(p_body));end $$;
revoke all on function public.add_project_message(uuid,text) from public,anon;
grant execute on function public.add_project_message(uuid,text) to authenticated;

commit;
